import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.FileReader;
import java.io.FileWriter;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedWriter 笔 = new BufferedWriter(new FileWriter("鱼.txt"));
        笔.write("大肥鱼");
        笔.newLine();
        笔.write("小橘");
        笔.newLine();
        笔.close();

        BufferedReader 眼 = new BufferedReader(new FileReader("鱼.txt"));
        String 行;
        int 号 = 0;
        while ((行 = 眼.readLine()) != null) {
            号 = 号 + 1;
        }
        眼.close();

        System.out.println("一共 " + 号 + " 行");
    }
}

import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;

class Fish implements Serializable {
    String 名字;
    transient int 条数 = 7;

    Fish(String 名字) {
        this.名字 = 名字;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Fish 原猫 = new Fish("小橘");

        ObjectOutputStream 出口 = new ObjectOutputStream(new FileOutputStream("猫.bin"));
        出口.writeObject(原猫);
        出口.close();

        ObjectInputStream 入口 = new ObjectInputStream(new FileInputStream("猫.bin"));
        Fish 回来的猫 = (Fish) 入口.readObject();
        入口.close();

        System.out.println(回来的猫.名字);
        System.out.println(回来的猫.条数);
    }
}
